package com.ercopac.ercopac_tracker.ticketing.domain;
import com.ercopac.ercopac_tracker.user.AppUser; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="ticket_read_states",uniqueConstraints=@UniqueConstraint(columnNames={"ticket_id","user_id"})) public class TicketReadState { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="ticket_id",nullable=false) private Ticket ticket; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private AppUser user; @Column(name="last_read_at",nullable=false) private Instant lastReadAt; public Ticket getTicket(){return ticket;} public void setTicket(Ticket v){ticket=v;} public AppUser getUser(){return user;} public void setUser(AppUser v){user=v;} public Instant getLastReadAt(){return lastReadAt;} public void setLastReadAt(Instant v){lastReadAt=v;} }
